-- Keep public Eos introductions about the person. Plot hooks remain in
-- discovery_metadata.storyHook and the authored character bible.
begin;

with biographies as (
  select * from jsonb_to_recordset($eos_public_bios$[{"template_id":"24000000-0000-4000-8012-000000000001","bio":"Lena is the emergency physician people look for when a shift turns difficult. Dryly funny beneath her composure, she wants to build a rehabilitation program and learn to leave work in someone else's capable hands."},{"template_id":"24000000-0000-4000-8012-000000000002","bio":"Cassian is a polished charter attorney with a wry sense of humor and a privately rebellious streak. He remembers the exact words people use in an argument and wants to write a charter he can defend even when someone he loves disagrees."},{"template_id":"24000000-0000-4000-8012-000000000003","bio":"Mara keeps Eos transit moving with blunt clarity and a remarkable sense of timing. She is quietly affectionate with the people she trusts, though taking a full week off would mean admitting Milo can run the board without her."},{"template_id":"24000000-0000-4000-8012-000000000004","bio":"Jonah curates the colony's memorial with patience and an ear for the parts of a story others skip. He cooks for late-working researchers and wants residents to be able to correct the archive he helped build."},{"template_id":"24000000-0000-4000-8012-000000000005","bio":"Talia knows how clothes can make someone feel at home and how to find materials everyone says are unavailable. Vibrant and generous, she is building a local label that gives the people who make it real ownership."},{"template_id":"24000000-0000-4000-8012-000000000006","bio":"Imani is a practical agricultural geneticist who talks to damaged plants while she works. She wants to make the colony's food supply more secure without forgetting that an orchard is also somewhere people love to spend time."},{"template_id":"24000000-0000-4000-8012-000000000007","bio":"Elian hears changes in the reservoir before most people see them and has a habit of finishing work others leave behind. Gentle and playful in private, he keeps promising himself an evening to perform his own music."},{"template_id":"24000000-0000-4000-8012-000000000008","bio":"Sora is an affectionate culinary apprentice who names failed recipes and steals dance breaks between shifts. She has a real opportunity to train away from Eos and wants the freedom to decide what kind of cook and person she will become."},{"template_id":"24000000-0000-4000-8012-000000000009","bio":"Naomi runs Solace with elegance, directness, and an immaculate paper planner. She stands by difficult decisions she made for the district, while working toward a settlement that repairs their costs rather than merely explaining them."},{"template_id":"24000000-0000-4000-8012-000000000010","bio":"Ari is a witty pollinator specialist who sketches insects on receipts and notices what others overlook. They are finishing an illustrated field guide under their own name and learning that warmth does not require agreeing with everyone."},{"template_id":"24000000-0000-4000-8012-000000000011","bio":"Rhea directs the port with a pilot's confidence and a careful eye for exits. Adventurous beneath her guarded manner, she is deciding whether her next command should take her away from the life she has built here."},{"template_id":"24000000-0000-4000-8012-000000000012","bio":"Kellan is a disciplined survey pilot who enjoys a challenge and cooks without recipes. He wants a career-making flight, but the promises he has made to other people matter as much as the view from the cockpit."},{"template_id":"24000000-0000-4000-8012-000000000013","bio":"Mina investigates customs shipments with a sharp ear, a mischievous smile, and little patience for easy explanations. She is loyal to the people she knows while learning that catching a contradiction does not mean knowing the whole person."},{"template_id":"24000000-0000-4000-8012-000000000014","bio":"Owen remembers a guest after one meeting and has made the Wayfarer Hotel feel like a place to land. Attentive to everyone else's needs, he keeps postponing the search for a home that belongs to him."},{"template_id":"24000000-0000-4000-8012-000000000015","bio":"Zahra is a resourceful cargo broker whose charm is backed by fiercely kept loyalties. She pays debts early and wants a business whose promises still hold when there is not enough space for everyone."},{"template_id":"24000000-0000-4000-8012-000000000016","bio":"Dax is the reactor engineer people trust with a hard repair and an unvarnished answer. He sings badly at work, fixes small things without being asked, and wants an understudy good enough to let him have a private life."},{"template_id":"24000000-0000-4000-8012-000000000017","bio":"Nia approaches a rover problem with grease on her hands and a joke ready for whoever doubts her. Fearless and affectionate, she wants a workshop that can keep Eos moving without waiting for imported parts."},{"template_id":"24000000-0000-4000-8012-000000000018","bio":"Mateo brings too much food to union meetings and never lets a misleading number pass unchallenged. Protective and stubborn, he is trying to build a labor movement strong enough to survive disagreement with him."},{"template_id":"24000000-0000-4000-8012-000000000019","bio":"Freya teaches exterior safety with exacting standards and keeps her favorite aurora photographs to herself. Warm once she trusts someone, she wants her students to develop judgment of their own rather than depend on her approval."},{"template_id":"24000000-0000-4000-8012-000000000020","bio":"Luc can turn a difficult fabrication job into a lesson and still find room for a teasing remark. He wants to open a craft school, even though teaching every method he knows means accepting that others will improve on them."},{"template_id":"24000000-0000-4000-8012-000000000021","bio":"Selene is an intense physicist who writes equations on her palms and dislikes being called mysterious. She cares about careful research and is learning to share credit and uncertainty with the colleagues beside her."},{"template_id":"24000000-0000-4000-8012-000000000022","bio":"Aya frames the aurora and the people beneath it with a restless photographer's eye. She keeps one image from every series for herself and is learning that a subject's trust matters more than her strongest exhibition shot."},{"template_id":"24000000-0000-4000-8012-000000000023","bio":"Elias is a steady rescue diver with a quiet sense of humor and a habit of tapping piano scales on tables. He wants to remain useful to his crew without being available for every dangerous shift."},{"template_id":"24000000-0000-4000-8012-000000000024","bio":"Priya carries interesting stones in every pocket and meets bold claims with playful skepticism. She wants to make a discovery she can stand behind, even if that means staking her reputation before every question is settled."},{"template_id":"24000000-0000-4000-8012-000000000025","bio":"Theo is an eager observatory technician who builds tiny antenna sculptures and rehearses questions he rarely asks as planned. He wants his methods to earn trust, including on the days he has to correct himself."},{"template_id":"24000000-0000-4000-8012-000000000026","bio":"Vesper turns transit hums into music and notices when someone leaves a room halfway through a song. Magnetic and protective, they want their club to thrive without selling the community's trust to a sponsor."},{"template_id":"24000000-0000-4000-8012-000000000027","bio":"Camille runs Quiet Orbit with discretion, compassion, and a precise memory for how guests take their tea. She wants to protect its hospitality while making sure the staff carrying it out are treated fairly."},{"template_id":"24000000-0000-4000-8012-000000000028","bio":"Rafael records stray sounds, speaks through playlists, and brings intensity to every collaboration. He wants to release music that succeeds without pretending the people who helped shape it were only background."},{"template_id":"24000000-0000-4000-8012-000000000029","bio":"June follows an archival clue with stubborn care, then bakes when her theory falls apart. Gentle and dryly funny, she wants to make independent research a life she can afford to keep living."},{"template_id":"24000000-0000-4000-8012-000000000030","bio":"Malik knows regulars by their shifts and refills a cup before anyone asks. His diner is a place of genuine care, though he is learning that generosity cannot replace the difficult conversations he still owes."},{"template_id":"24000000-0000-4000-8012-000000000031","bio":"Amaya is a quick-witted emergency cadet who memorizes routes for fun and puts far too much sugar in her coffee. She wants to earn an independent field qualification by admitting mistakes as plainly as successes."},{"template_id":"24000000-0000-4000-8012-000000000032","bio":"Celeste brings precise questions and two pens she will not lend to civic meetings. Idealistic beneath her composure, she wants to pursue public office openly and accept that good policy can still need revision."},{"template_id":"24000000-0000-4000-8012-000000000033","bio":"Milo is a friendly transit apprentice who fixes broken headphones and knows which platform has the best acoustics. He wants credit for a useful improvement and enough confidence to admit whose help made it possible."},{"template_id":"24000000-0000-4000-8012-000000000034","bio":"Liora is a sunny, mischievous orchard apprentice who names difficult trees after relatives and saves the best fruit for friends. She wants a small section of the orchard to steward through her own work."},{"template_id":"24000000-0000-4000-8012-000000000035","bio":"Hana keeps her water samples in color order and paints tiny landscapes on maintenance tags. Calm and playful, she wants to lead a study whose measurements she can explain and defend herself."},{"template_id":"24000000-0000-4000-8012-000000000036","bio":"Zoe remembers people by what made them laugh and carries spare hydration tabs for anyone who needs one. She wants a lasting career in community care that leaves room for an ambitious, pleasurable life of her own."},{"template_id":"24000000-0000-4000-8012-000000000037","bio":"Yara can balance a tool on her knuckles while explaining exactly what is wrong with a shuttle. Bold and competitive, she wants flight certification and proper credit for the mechanical work that got her there."},{"template_id":"24000000-0000-4000-8012-000000000038","bio":"Leona welcomes arrivals in their own languages and can recognize regular guests by their footsteps. She loves her family while wanting to travel for work on her own behalf, not only arrange other people's journeys."},{"template_id":"24000000-0000-4000-8012-000000000039","bio":"Micah makes a game of quick deliveries and has a habit of spending his travel savings on friends. Charming and kind, he is learning to name his own limits without becoming less generous."},{"template_id":"24000000-0000-4000-8012-000000000040","bio":"Poppy makes jewelry from failed prints and laughs when a prototype sparks after everyone is safe. Inventive and stubborn, she wants her first successful product to carry her own name."},{"template_id":"24000000-0000-4000-8012-000000000041","bio":"Samira remembers everyone's food needs at a union meeting and writes notes in fragments of verse. Empathetic and strategic, she wants to lead openly without treating her own ambition as disloyalty."},{"template_id":"24000000-0000-4000-8012-000000000042","bio":"Noah designs pressure suits with a rescue trainer's eye for the person inside them. Steady and dryly funny, he wants properly fitting equipment to be a standard commitment rather than a favor he funds himself."},{"template_id":"24000000-0000-4000-8012-000000000043","bio":"Iris draws constellations on drink sleeves and knows more catalogs than she can recite without smiling. She wants her research judged on its own merits, including when her well-connected brother offers help."},{"template_id":"24000000-0000-4000-8012-000000000044","bio":"Noura tests language theories aloud and labels tea blends after unsolved grammar problems. Witty and intense, she wants independent credit for careful work and the freedom to correct a promising idea in public."},{"template_id":"24000000-0000-4000-8012-000000000045","bio":"Kenji carries emergency candy on night-side rover routes and drums on the wheel while instruments recalibrate. Loyal to his crew, he wants to make a film about workers whose ordinary lives rarely make the expedition footage."},{"template_id":"24000000-0000-4000-8012-000000000046","bio":"Eden sketches on her gloves and remembers the stories people attach to their tattoos. Bold and affectionate, she wants her first independent exhibition to introduce her through her work rather than her sister or mentors."},{"template_id":"24000000-0000-4000-8012-000000000047","bio":"Mae hides tiny jokes in the sets she builds and measures a room by pacing it. Soft-spoken and inventive, she wants to stage a small, strange show that is unmistakably hers."}]$eos_public_bios$::jsonb)
    as entry(template_id uuid, bio text)
)
update public.together_character_templates as template
set biography=biographies.bio,
    discovery_metadata=case
      when template.discovery_metadata->>'summary'=template.biography
      then jsonb_set(template.discovery_metadata,'{summary}',to_jsonb(biographies.bio),true)
      else template.discovery_metadata
    end,
    updated_at=now()
from biographies
where template.id=biographies.template_id
  and template.creator_id is null
  and template.discovery_metadata->>'residentWorldSlug'='eos-meridian'
  and nullif(template.discovery_metadata->>'storyHook','') is not null
  and right(trim(template.biography),length(trim(template.discovery_metadata->>'storyHook')))
      =trim(template.discovery_metadata->>'storyHook');

commit;
